create extension if not exists pgcrypto;
alter table public.products add column if not exists required_fields jsonb not null default '[]'::jsonb;
alter table public.orders add column if not exists customer_data jsonb not null default '{}'::jsonb;
create table if not exists public.smm_services(id uuid primary key default gen_random_uuid(),name text not null,platform text not null,description text,price_per_1000 numeric(14,4) not null check(price_per_1000>=0),min_quantity integer not null default 100,max_quantity integer not null default 10000,icon text not null default 'rocket',sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.smm_orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,user_id uuid not null references public.profiles(id),service_id uuid not null references public.smm_services(id),target_url text not null,quantity integer not null,total numeric(14,2) not null,status text not null default 'pending',notes text,provider_reference text,admin_note text,refund_transaction_id uuid unique references public.wallet_transactions(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
alter table public.smm_services enable row level security;alter table public.smm_orders enable row level security;
drop policy if exists smm_services_public_read on public.smm_services;create policy smm_services_public_read on public.smm_services for select using(is_active or public.is_admin());
drop policy if exists smm_services_admin_all on public.smm_services;create policy smm_services_admin_all on public.smm_services for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists smm_orders_read on public.smm_orders;create policy smm_orders_read on public.smm_orders for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists smm_orders_admin_all on public.smm_orders;create policy smm_orders_admin_all on public.smm_orders for all to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.purchase_product_v6(p_product_id uuid,p_idempotency_key uuid,p_coupon_code text default null,p_customer_data jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;oid uuid;begin r:=public.purchase_product_v5(p_product_id,p_idempotency_key,p_coupon_code);oid:=(r->>'order_id')::uuid;if oid is not null then update public.orders set customer_data=coalesce(p_customer_data,'{}'::jsonb) where id=oid;end if;return r;end$$;
create or replace function public.create_smm_order(p_service_id uuid,p_target_url text,p_quantity integer,p_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();s public.smm_services%rowtype;w public.wallets%rowtype;t numeric(14,2);oid uuid;num text;begin if u is null then raise exception 'يجب تسجيل الدخول';end if;select * into s from public.smm_services where id=p_service_id and is_active=true for update;if not found then raise exception 'الخدمة غير متاحة';end if;if p_quantity<s.min_quantity or p_quantity>s.max_quantity then raise exception 'الكمية خارج الحدود';end if;t:=round((p_quantity::numeric/1000)*s.price_per_1000,2);select * into w from public.wallets where user_id=u for update;if not found or w.balance<t then raise exception 'الرصيد غير كاف';end if;num:='SMM-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));insert into public.smm_orders(order_number,user_id,service_id,target_url,quantity,total,notes) values(num,u,p_service_id,trim(p_target_url),p_quantity,t,p_notes) returning id into oid;update public.wallets set balance=balance-t,updated_at=now() where user_id=u;insert into public.wallet_transactions(user_id,type,amount,balance_before,balance_after,description,reference_code) values(u,'purchase',-t,w.balance,w.balance-t,'طلب خدمة SMM','SMM-'||replace(gen_random_uuid()::text,'-',''));insert into public.notifications(user_id,title,body,type) values(u,'تم إنشاء طلب SMM','طلبك قيد المراجعة والتنفيذ','order');return jsonb_build_object('success',true,'order_id',oid);end$$;
create or replace function public.admin_update_smm_order(p_order_id uuid,p_status text,p_provider_reference text default null,p_admin_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare o public.smm_orders%rowtype;w public.wallets%rowtype;tx uuid;begin if not public.is_admin() then raise exception 'غير مصرح';end if;select * into o from public.smm_orders where id=p_order_id for update;if not found then raise exception 'الطلب غير موجود';end if;if p_status in('cancelled','refunded') and o.refund_transaction_id is null then select * into w from public.wallets where user_id=o.user_id for update;update public.wallets set balance=balance+o.total,updated_at=now() where user_id=o.user_id;insert into public.wallet_transactions(user_id,type,amount,balance_before,balance_after,description,reference_code) values(o.user_id,'refund',o.total,w.balance,w.balance+o.total,'استرداد طلب SMM','SMM-REF-'||replace(gen_random_uuid()::text,'-','')) returning id into tx;update public.smm_orders set refund_transaction_id=tx where id=o.id;end if;update public.smm_orders set status=p_status,provider_reference=p_provider_reference,admin_note=p_admin_note,updated_at=now(),completed_at=case when p_status='delivered' then now() else completed_at end where id=o.id;insert into public.notifications(user_id,title,body,type) values(o.user_id,'تحديث طلب SMM',coalesce(p_admin_note,'تم تحديث حالة طلبك'),'order');return jsonb_build_object('success',true);end$$;
grant execute on function public.purchase_product_v6(uuid,uuid,text,jsonb) to authenticated;grant execute on function public.create_smm_order(uuid,text,integer,text) to authenticated;grant execute on function public.admin_update_smm_order(uuid,text,text,text) to authenticated;
